body.script:
//

  /* ── 1. NORMALIZE & CLEAN PATH HELPER ── */
  function getCleanPath(rawPath) {
    var p = (rawPath || window.location.pathname).toLowerCase().replace('.html', '');
    if (p.indexOf('friender') !== -1) return '/casestudy/friender-case-study';
    if (p.indexOf('wexa') !== -1) return '/casestudy/wexa';
    p = p.replace(/^\/p\//, '/');
    if (!p.startsWith('/')) p = '/' + p;
    return p;
  }

  /* ── 2. STRIP /p/ AND .HTML FROM ADDRESS BAR ── */
  (function() {
    var stored = sessionStorage.getItem('spa_target_route');
    if (stored) {
      sessionStorage.removeItem('spa_target_route');
      window.history.replaceState(null, document.title, stored + window.location.search + window.location.hash);
      return;
    }
    var path = window.location.pathname;
    var cleanPath = getCleanPath(path);
    if (path !== cleanPath) {
      window.history.replaceState(null, document.title, cleanPath + window.location.search + window.location.hash);
    }
  })();

  /* ── 3. UNKNOWN URL REDIRECT ── */
  (function() {
    var known = ['/', '/casestudy', '/about', '/playground', '/casestudy/friender-case-study', '/casestudy/wexa'];
    var path = getCleanPath(window.location.pathname);
    var isKnown = known.some(function(k) { return path === k; });
    if (!isKnown) { window.location.replace('/'); }
  })();

  /* ── SKELETON LOADER HANDLER ── */
  function setupImageSkeleton(img) {
    var wrapper = img.closest('.pm-img-wrap, .pm-photo, .pm-pg-image, .pm-case-study-single-image, .fcs-image, .pm-bottom-gallery');
    function reveal() {
      img.classList.add('pm-img-loaded');
      if (wrapper) wrapper.classList.add('pm-img-loaded');
    }
    if (img.complete && img.naturalWidth > 0) {
      reveal();
    } else {
      img.addEventListener('load', reveal, { once: true });
      img.addEventListener('error', reveal, { once: true });
    }
  }

  function loadImagesForContainer(containerId) {
    if (!containerId) return;
    var container = document.getElementById(containerId);
    if (!container) return;

    var images = container.querySelectorAll('img[data-src]');
    images.forEach(function(img) {
      setupImageSkeleton(img);
      img.setAttribute('src', img.getAttribute('data-src'));
      img.removeAttribute('data-src');
    });
  }

  /* ── SKELETON LOADER INITIALIZATION ── */
  (function() {
    document.querySelectorAll('img').forEach(function(img) {
      setupImageSkeleton(img);
    });
  })();

  /* ── ENTRANCE ANIMATION ── */
  function pmRunEntranceAnimation() {
    requestAnimationFrame(function() {
      requestAnimationFrame(function() {
        var inners = document.querySelectorAll('.pm-inner');
        inners.forEach(function(inner) {
          var pageDiv = inner.closest('[id^="pm-"]');
          if (pageDiv && pageDiv.style.display === 'none') return;
          var children = Array.prototype.slice.call(inner.children);
          children.forEach(function(child, i) {
            child.classList.remove('pm-animate-in');
            child.style.animationDelay = '';
            void child.offsetWidth;
            child.style.animationDelay = (60 + i * 80) + 'ms';
            child.classList.add('pm-animate-in');
          });
        });
      });
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', pmRunEntranceAnimation);
  } else {
    pmRunEntranceAnimation();
  }

  /* ── LIGHTBOX ── */
  (function() {
    var lb      = document.getElementById('pm-lightbox');
    var lbImg   = document.getElementById('pm-lightbox-img');
    var lbClose = document.getElementById('pm-lightbox-close');
    var lbPrev  = document.getElementById('pm-lightbox-prev');
    var lbNext  = document.getElementById('pm-lightbox-next');
    var images  = [];
    var current = 0;

    function collect() {
      images = [];
      document.querySelectorAll('.pm-pg-image img').forEach(function(el) {
        images.push({ src: el.src || el.getAttribute('data-src'), alt: el.alt || '' });
      });
    }

    function show(idx) {
      if (idx < 0 || idx >= images.length) return;
      current = idx;
      lbImg.src = images[current].src;
      lbImg.alt = images[current].alt;
      if (lbPrev) {
        lbPrev.style.opacity = current > 0 ? '0.85' : '0.25';
        lbPrev.style.pointerEvents = current > 0 ? 'auto' : 'none';
      }
      if (lbNext) {
        lbNext.style.opacity = current < images.length - 1 ? '0.85' : '0.25';
        lbNext.style.pointerEvents = current < images.length - 1 ? 'auto' : 'none';
      }
    }

    function open(src) {
      collect();
      var idx = 0;
      for (var i = 0; i < images.length; i++) {
        if (images[i].src === src) { idx = i; break; }
      }
      show(idx);
      lb.classList.add('active');
      document.body.style.overflow = 'hidden';
    }

    function close() {
      lb.classList.remove('active');
      document.body.style.overflow = '';
      lbImg.src = '';
    }

    document.addEventListener('click', function(e) {
      var img = e.target.closest('.pm-pg-image img');
      if (!img) return;
      var src = img.src || img.getAttribute('data-src');
      var isMobile = ('ontouchstart' in window) || window.matchMedia('(max-width: 480px)').matches;
      if (isMobile) { window.open(src, '_blank'); }
      else { open(src); }
    });

    if (lbPrev) lbPrev.addEventListener('click', function(e) { e.stopPropagation(); show(current - 1); });
    if (lbNext) lbNext.addEventListener('click', function(e) { e.stopPropagation(); show(current + 1); });
    if (lbClose) lbClose.addEventListener('click', close);
    lb.addEventListener('click', function(e) { if (e.target === lb) close(); });

    document.addEventListener('keydown', function(e) {
      if (!lb.classList.contains('active')) return;
      if (e.key === 'Escape') close();
      if (e.key === 'ArrowLeft') show(current - 1);
      if (e.key === 'ArrowRight') show(current + 1);
    });
  })();

  /* ── SMOOTH SCROLL (desktop) ── */
  (function() {
    var st = 0, sc = 0, ease = 0.08, raf = null, running = false;
    function lerp(a,b,t){return a+(b-a)*t;}
    function tick(){
      sc = lerp(sc,st,ease);
      if(Math.abs(st-sc)<0.5){sc=st;window.scrollTo(0,sc);running=false;raf=null;return;}
      window.scrollTo(0,sc);raf=requestAnimationFrame(tick);
    }
    if(!('ontouchstart' in window)&&window.matchMedia('(min-width:481px)').matches){
      window.addEventListener('wheel',function(e){
        e.preventDefault();
        if(!running) {
          st = window.scrollY;
          sc = window.scrollY;
        }
        st += e.deltaY*1.2;
        st = Math.max(0,Math.min(st,document.body.scrollHeight-window.innerHeight));
        if(!running){running=true;if(raf)cancelAnimationFrame(raf);raf=requestAnimationFrame(tick);}
      },{passive:false});
    }
  })();

  /* ── GLOBAL SPA & ROUTER ── */
  var titleMap = {
    '/': 'Bishal Mistri — Product Designer',
    '/casestudy': 'Case Study — Bishal Mistri',
    '/about': 'About — Bishal Mistri',
    '/playground': 'Playground — Bishal Mistri',
    '/casestudy/friender-case-study': 'Friender Case Study — Bishal Mistri',
    '/casestudy/wexa': 'Wexa AI — Bishal Mistri'
  };

  var allPageIds = ['pm-cs','pm-play','pm-about','pm-friender','pm-wexa'];

  function getIdx(path) {
    var p = getCleanPath(path);
    if (p.indexOf('friender') !== -1 || p.indexOf('wexa') !== -1 || p === '/casestudy') return 1;
    if (p.indexOf('playground') !== -1) return 2;
    if (p.indexOf('about') !== -1) return 3;
    return 0;
  }

  function getContentId(path) {
    var p = getCleanPath(path);
    if (p.indexOf('friender') !== -1) return 'pm-friender';
    if (p.indexOf('wexa') !== -1) return 'pm-wexa';
    if (p === '/casestudy') return 'pm-cs';
    if (p.indexOf('playground') !== -1) return 'pm-play';
    if (p.indexOf('about') !== -1) return 'pm-about';
    return null;
  }

  var items = document.querySelectorAll('.pm-nav-item');
  var pill  = document.getElementById('pm-pill');
  var wrap  = document.getElementById('pm-content-wrap');
  var W = 56;

  function setActive(idx) {
    items.forEach(function(el,i){ el.classList.toggle('active', i===idx); });
    if (pill) pill.style.transform = 'translateX('+(idx*W)+'px)';
  }

  function syncNavToCurrentURL() {
    var current = getCleanPath(window.location.pathname);
    var idx = getIdx(current);
    setActive(idx);
  }

  function showContentById(contentId) {
    allPageIds.forEach(function(id) {
      var el = document.getElementById(id);
      if (el) el.style.display = 'none';
    });
    if (contentId) {
      var el = document.getElementById(contentId);
      if (el) {
        el.style.display = '';
        loadImagesForContainer(contentId);
      }
    }
  }

  function navigateSPA(href, idx) {
    var cleanHref = getCleanPath(href);
    if (idx === undefined) idx = getIdx(cleanHref);
    setActive(idx);

    var contentId = getContentId(cleanHref);

    // If navigating to Home
    if (!contentId || cleanHref === '/') {
      if (!document.querySelector('.pm-hero')) {
        window.location.href = '/';
        return;
      }
      allPageIds.forEach(function(id) {
        var el = document.getElementById(id);
        if (el) el.style.display = 'none';
      });
      document.title = titleMap['/'] || 'Bishal Mistri — Product Designer';
      history.pushState({ idx: 0, href: '/' }, document.title, '/');
      window.scrollTo(0, 0);
      pmRunEntranceAnimation();
      return;
    }

    // If navigating to a Subpage / Case Study
    var targetEl = document.getElementById(contentId);
    if (targetEl) {
      if (wrap) { wrap.style.transition = 'opacity 0.18s ease'; wrap.style.opacity = '0'; }
      showContentById(contentId);
      document.title = titleMap[cleanHref] || 'Bishal Mistri — Product Designer';
      history.pushState({ idx: idx, href: cleanHref }, document.title, cleanHref);
      window.scrollTo(0, 0);
      requestAnimationFrame(function() {
        if (wrap) wrap.style.opacity = '1';
        pmRunEntranceAnimation();
      });
    } else {
      sessionStorage.setItem('spa_target_route', cleanHref);
      window.location.href = '/p/casestudy.html';
    }
  }

  /* ── BACK BUTTON LOGIC ── */
  window.pmGoBack = function(e) {
    if (e) e.preventDefault();
    if (window.history.length > 1 && document.referrer.includes(window.location.hostname)) {
      window.history.back();
    } else {
      navigateSPA('/casestudy', 1);
    }
  };

  /* ── INITIAL LOAD ROUTER ── */
  (function() {
    var cleanPath = getCleanPath(window.location.pathname);
    var id = getContentId(cleanPath);
    if (id) {
      var el = document.getElementById(id);
      if (el) {
        el.style.display = '';
        el.style.visibility = 'visible';
        loadImagesForContainer(id);
        if (titleMap[cleanPath]) document.title = titleMap[cleanPath];
      }
    }
  })();

  /* ── NAV CLICKS ── */
  items.forEach(function(el) {
    el.addEventListener('click', function() {
      var idx  = parseInt(el.getAttribute('data-index'));
      var href = el.getAttribute('data-href');
      if (!href) return;
      navigateSPA(href, idx);
    });
  });

  /* ── IN-PAGE LINK CLICKS ── */
  document.addEventListener('click', function(e) {
    var link = e.target.closest('a');
    if (!link) return;
    var href = link.getAttribute('href');
    if (href && href.startsWith('/') && !href.startsWith('//') && !link.target && !href.startsWith('mailto:')) {
      e.preventDefault();
      navigateSPA(href);
    }
  });

  /* ── BROWSER FORWARD / BACK & CACHE RESTORE ── */
  window.addEventListener('popstate', function(e) {
    var currentPath = window.location.pathname.toLowerCase();
    navigateSPA(currentPath);
    syncNavToCurrentURL();
  });

  window.addEventListener('pageshow', function() {
    syncNavToCurrentURL();
  });

  /* ── INIT FLOATING NAV PILL ── */
  (function initNav() {
    var idx = getIdx(window.location.pathname);
    if (pill) pill.style.transition = 'none';
    setActive(idx);
    requestAnimationFrame(function(){
      requestAnimationFrame(function(){ if (pill) pill.style.transition = ''; });
    });
  })();


/* ── CUSTOM CURSOR & CLICK ANIMATION HANDLER ── */
  (function() {
    var cursor = document.getElementById('pm-zoom-cursor');
    var items = document.querySelectorAll('.pm-pin-item');
    if (!cursor || !items.length) return;

    var mouseX = 0, mouseY = 0;
    var cursorX = 0, cursorY = 0;
    var isHovering = false;

    // Smooth cursor follow lerp
    function updateCursor() {
      var dx = mouseX - cursorX;
      var dy = mouseY - cursorY;
      cursorX += dx * 0.2;
      cursorY += dy * 0.2;
      cursor.style.left = cursorX + 'px';
      cursor.style.top = cursorY + 'px';
      requestAnimationFrame(updateCursor);
    }
    requestAnimationFrame(updateCursor);

    document.addEventListener('mousemove', function(e) {
      mouseX = e.clientX;
      mouseY = e.clientY;
    });

    items.forEach(function(item) {
      item.addEventListener('mouseenter', function() {
        isHovering = true;
        cursor.classList.add('active');
      });

      item.addEventListener('mouseleave', function() {
        isHovering = false;
        cursor.classList.remove('active');
        item.classList.remove('clicked');
        cursor.classList.remove('clicked');
      });

      item.addEventListener('mousedown', function() {
        if (isHovering) {
          item.classList.add('clicked');
          cursor.classList.add('clicked');
        }
      });

      item.addEventListener('mouseup', function() {
        item.classList.remove('clicked');
        cursor.classList.remove('clicked');
      });
    });
  })();

  //
